section.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/raci-matrix.json",
  "title": "RACIMatrix",
  "type": "object",
  "required": ["project_id", "header", "roster", "wbs_open_leaves", "rows", "review_log"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "wbs_id": {"type": "string", "pattern": "^[0-9]+(\\.[0-9]+)*$"},
    "role_id": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9_-]*$",
      "not": {"enum": ["team", "Team", "TEAM", "tbd", "TBD", "various", "ai", "AI", "agent", "automation", "bot"]}
    },
    "anchor": {"type": "string", "pattern": "^(charter#[A-Za-z0-9._-]+|wbs-dict#[0-9]+(\\.[0-9]+)*|stakeholders#[A-Za-z0-9._-]+)$"},
    "wbs_id_list": {"type": "array", "items": {"$ref": "#/definitions/wbs_id"}, "uniqueItems": true}
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "project_id": {"type": "string", "minLength": 2},
    "header": {
      "type": "object",
      "required": ["owner", "status", "trigger", "version", "last_reviewed"],
      "additionalProperties": false,
      "properties": {
        "owner": {
          "type": "object",
          "required": ["role", "person"],
          "properties": {"role": {"$ref": "#/definitions/role_id"}, "person": {"type": "string", "minLength": 2}}
        },
        "status": {"enum": ["draft", "published"]},
        "trigger": {"enum": ["kickoff", "roster_delta", "quarterly_review"]},
        "version": {"type": "string", "pattern": "^[0-9]+\\.[0-9]+(\\.[0-9]+)?$"},
        "last_reviewed": {"$ref": "#/definitions/date"}
      }
    },
    "roster": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "type": "object",
        "required": ["role", "person"],
        "properties": {"role": {"$ref": "#/definitions/role_id"}, "person": {"type": "string", "minLength": 2}}
      }
    },
    "wbs_open_leaves": {"$ref": "#/definitions/wbs_id_list", "minItems": 1},
    "rows": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["wbs_id", "deliverable", "responsible", "accountable", "consulted", "informed", "evidence", "status"],
        "additionalProperties": false,
        "properties": {
          "wbs_id": {"$ref": "#/definitions/wbs_id"},
          "deliverable": {"type": "string", "minLength": 2},
          "responsible": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"$ref": "#/definitions/role_id"}},
          "accountable": {"$ref": "#/definitions/role_id"},
          "consulted": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/definitions/role_id"}},
          "informed": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/definitions/role_id"}},
          "evidence": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/definitions/anchor"}},
          "status": {"enum": ["anchored", "proposed", "orphaned"]},
          "over_consultation_reviewed": {"type": "boolean"}
        },
        "if": {"properties": {"status": {"const": "anchored"}}},
        "then": {"properties": {"evidence": {"minItems": 1}}}
      }
    },
    "roster_delta": {
      "type": "object",
      "required": ["change", "role", "person", "effective_date", "refresh_deadline", "rows_changed", "rows_orphaned", "rows_reassigned"],
      "additionalProperties": false,
      "properties": {
        "change": {"enum": ["join", "leave", "role_change"]},
        "role": {"$ref": "#/definitions/role_id"},
        "person": {"type": "string", "minLength": 2},
        "effective_date": {"$ref": "#/definitions/date"},
        "refresh_deadline": {"$ref": "#/definitions/date"},
        "rows_changed": {"$ref": "#/definitions/wbs_id_list"},
        "rows_orphaned": {"$ref": "#/definitions/wbs_id_list"},
        "rows_reassigned": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["wbs_id", "column", "role", "evidence"],
            "properties": {
              "wbs_id": {"$ref": "#/definitions/wbs_id"},
              "column": {"enum": ["responsible", "accountable", "consulted", "informed"]},
              "role": {"$ref": "#/definitions/role_id"},
              "evidence": {"type": "array", "minItems": 1, "items": {"$ref": "#/definitions/anchor"}}
            }
          }
        }
      }
    },
    "review_log": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["reviewed_at", "kind"],
        "properties": {
          "reviewed_at": {"$ref": "#/definitions/date"},
          "kind": {"enum": ["publish", "quarterly_review"]},
          "notification": {
            "type": "object",
            "required": ["channel", "sent_on", "recipients"],
            "properties": {
              "channel": {"type": "string", "minLength": 1},
              "sent_on": {"$ref": "#/definitions/date"},
              "recipients": {
                "type": "array",
                "minItems": 1,
                "items": {
                  "type": "object",
                  "required": ["role", "person", "rows"],
                  "properties": {
                    "role": {"$ref": "#/definitions/role_id"},
                    "person": {"type": "string", "minLength": 2},
                    "rows": {"$ref": "#/definitions/wbs_id_list", "minItems": 1}
                  }
                }
              }
            }
          },
          "rows_removed": {"type": "integer", "minimum": 0},
          "rows_reassigned": {"type": "integer", "minimum": 0},
          "rows_still_proposed": {"type": "integer", "minimum": 0}
        },
        "allOf": [
          {"if": {"properties": {"kind": {"const": "publish"}}}, "then": {"required": ["notification"]}},
          {"if": {"properties": {"kind": {"const": "quarterly_review"}}}, "then": {"required": ["rows_removed", "rows_reassigned", "rows_still_proposed"]}}
        ]
      }
    }
  },
  "allOf": [
    {
      "if": {"properties": {"header": {"properties": {"status": {"const": "published"}}}}},
      "then": {
        "properties": {
          "rows": {"items": {"properties": {"status": {"const": "anchored"}}}},
          "review_log": {"minItems": 1, "contains": {"properties": {"kind": {"const": "publish"}}, "required": ["kind"]}}
        }
      }
    },
    {
      "if": {"properties": {"header": {"properties": {"trigger": {"const": "roster_delta"}}}}},
      "then": {"required": ["roster_delta"]}
    },
    {
      "if": {"properties": {"header": {"properties": {"trigger": {"const": "quarterly_review"}}}}},
      "then": {"properties": {"review_log": {"minItems": 1, "contains": {"properties": {"kind": {"const": "quarterly_review"}}, "required": ["kind"]}}}}
    }
  ]
}
